    62  /** Convert a STRUCT to one or more VPs
    63   *
    64   */
    65  ssize_t fr_struct_from_network(TALLOC_CTX *ctx, fr_dcursor_t *cursor,
    66                                 fr_dict_attr_t const *parent, uint8_t const *data, size_t data_len,
    67                                 void *decode_ctx,
    68                                 fr_decode_value_t decode_value, fr_decode_value_t decode_tlv)
    69  {
    70          unsigned int            child_num;
    71          uint8_t const           *p = data, *end = data + data_len;
    72          fr_dict_attr_t const    *child;
    73          fr_pair_list_t          head;
    74          fr_dcursor_t            child_cursor;
    75          fr_pair_t               *vp, *key_vp;
    76          unsigned int            offset = 0;
    77
    78          fr_pair_list_init(&head);
    79          if (data_len < 1) return -1; /* at least one byte of data */
    80
    81          FR_PROTO_HEX_DUMP(data, data_len, "fr_struct_from_network");
    82
    83          /*
    84           *      Record where we were in the list when this function was called
    85           */
    86          fr_dcursor_init(&child_cursor, &head);
    87          child_num = 1;
    88          key_vp = NULL;
    89
    90          /*
    91           *      Decode structs with length prefixes.
    92           */
    93          if (da_is_length_field(parent)) {
    94                  size_t struct_len;
    95
    96                  struct_len = (p[0] << 8) | p[1];
    97                  if ((struct_len + 2) > data_len) goto unknown;
    98
    99                  data_len = struct_len + 2;
   100                  end = data + data_len;
   101                  p += 2;
   102          }
   103
   104          while (p < end) {
   105                  size_t child_length;
   106
   107                  /*
   108                   *      Go to the next child.  If it doesn't exist, we're done.
   109                   */
   110                  child = fr_dict_attr_child_by_num(parent, child_num);
   111                  if (!child) break;
   112
   113                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - child %s (%d)", child->name, child->attr);
   114
   115                  /*
   116                   *      Check for bit fields.
   117                   */
   118                  if (da_is_bit_field(child)) {
   119                          uint8_t array[8];
   120                          unsigned int num_bits;
   121                          uint64_t value;
   122
   123                          num_bits = offset + child->flags.length;
   124                          if ((end - p) < fr_bytes_from_bits(num_bits)) goto unknown;
   125
   126                          memset(array, 0, sizeof(array));
   127                          memcpy(&array[0], p, fr_bytes_from_bits(num_bits));
   128
   129                          if (offset > 0) array[0] &= (1 << (8 - offset)) - 1; /* mask off bits we don't care about */
   130
   131                          memcpy(&value, &array[0], sizeof(value));
   132                          value = htonll(value);
   133                          value >>= (8 - offset); /* move it to the lower bits */
   134                          value >>= (56 - child->flags.length);
   135
   136                          vp = fr_pair_afrom_da(ctx, child);
   137                          if (!vp) {
   138                                  FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   139                                  goto unknown;
   140                          }
   141
   142                          switch (child->type) {
   143                                  case FR_TYPE_BOOL:
   144                                          vp->vp_bool = value;
   145                                          break;
   146
   147                                  case FR_TYPE_UINT8:
   148                                          vp->vp_uint8 = value;
   149                                          break;
   150
   151                                  case FR_TYPE_UINT16:
   152                                          vp->vp_uint16 = value;
   153                                          break;
   154
   155                                  case FR_TYPE_UINT32:
   156                                          vp->vp_uint32 = value;
   157                                          break;
   158
   159                                  case FR_TYPE_UINT64:
   160                                          vp->vp_uint64 = value;
   161                                          break;
   162
   163                                  default:
   164                                          goto unknown;
   165                          }
   166
   167                          vp->type = VT_DATA;
   168                          vp->vp_tainted = true;
   169                          fr_dcursor_append(&child_cursor, vp);
   170                          p += (num_bits >> 3); /* go to the LAST bit, not the byte AFTER the last bit */
   171                          offset = num_bits & 0x07;
   172                          child_num++;
   173                          continue;
   174                  }
   175                  offset = 0;     /* reset for non-bit-field attributes */
   176
   177                  /*
   178                   *      Decode child TLVs, according to the parent attribute.
   179                   */
   180                  if (child->type == FR_TYPE_TLV) {
   181                          ssize_t slen;
   182
   183                          fr_assert(!key_vp);
   184
   185                          if (!decode_tlv) {
   186                                  fr_strerror_const("Decoding TLVs requires a decode_tlv() function to be passed");
   187                                  return -(p - data);
   188                          }
   189
   190                          /*
   191                           *      Decode EVERYTHING as a TLV.
   192                           */
   193                          while (p < end) {
   194                                  slen = decode_tlv(ctx, &child_cursor, fr_dict_by_da(child), child, p, end - p, decode_ctx);
   195                                  if (slen < 0) goto unknown;
   196                                  p += slen;
   197                          }
   198
   199                          goto done;
   200                  }
   201
   202                  child_length = child->flags.length;
   203
   204                  /*
   205                   *      If this field overflows the input, then *all*
   206                   *      of the input is suspect.
   207                   */
   208                  if ((p + child_length) > end) {
   209                          FR_PROTO_TRACE("fr_struct_from_network - child length %zd overflows buffer", child_length);
   210                          goto unknown;
   211                  }
   212
   213                  if (!child_length) child_length = (end - p);
   214
   215                  /*
   216                   *      Magic values get the callback called.
   217                   *
   218                   *      Note that if this is an *array* of DNS labels,
   219                   *      the callback should deal with this.
   220                   */
   221                  if (decode_value) {
   222                          ssize_t slen;
   223
   224                          slen = decode_value(ctx, &child_cursor, fr_dict_by_da(child), child, p, child_length, decode_ctx);
   225                          if (slen < 0) return slen - (p - data);
   226
   227                          p += slen;      /* not always the same as child->flags.length */
   228                          child_num++;    /* go to the next child */
   229                          if (fr_dict_attr_is_key_field(child)) key_vp = fr_dcursor_tail(&child_cursor);
   230                          continue;
   231                  }
   232
   233                  /*
   234                   *      We only allow a limited number of data types
   235                   *      inside of a struct.
   236                   */
   237                  switch (child->type) {
   238                  default:
   239                          FR_PROTO_TRACE("fr_struct_from_network - unknown child type");
   240                          goto unknown;
   241
   242                  case FR_TYPE_LEAF:
   243                          break;
   244                  }
   245
   246                  vp = fr_pair_afrom_da(ctx, child);
   247                  if (!vp) {
   248                          FR_PROTO_TRACE("fr_struct_from_network - failed allocating child VP");
   249                          goto unknown;
   250                  }
   251
   252                  /*
   253                   *      No protocol-specific data types here (yet).
   254                   *
   255                   *      If we can't decode this field, then the entire
   256                   *      structure is treated as a raw blob.
   257                   */
   258                  if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da, p, child_length, true) < 0) {
   259                          FR_PROTO_TRACE("fr_struct_from_network - failed decoding child VP");
   260                          talloc_free(vp);
   260                          talloc_free(vp);
   261                  unknown:
   262                          fr_pair_list_free(&head);
   263
   264                          vp = fr_raw_from_network(ctx, parent, data, data_len);
   265                          if (!vp) return -1;
   266
   267                          /*
   268                           *      And append this one VP to the output cursor.
   269                           */
   270                          fr_dcursor_append(cursor, vp);
   271                          return data_len;
   272                  }
   273
   274                  vp->type = VT_DATA;
   275                  vp->vp_tainted = true;
   276                  fr_dcursor_append(&child_cursor, vp);
   277
   278                  if (fr_dict_attr_is_key_field(vp->da)) key_vp = vp;
   279
   280                  /*
   281                   *      Note that we're decoding fixed fields here.
   282                   *      So we skip the input based on the *known*
   283                   *      length, and not on the *decoded* length.
   284                   */
   285                  p += child_length;
   286                  child_num++;    /* go to the next child */
   287          }
   288
   289          /*
   290           *      Is there a substructure after this one?  If so, go
   291           *      decode it.
   292           */
   293          if (key_vp) {
   294                  ssize_t slen;
   295                  fr_dict_enum_t const *enumv;
   296                  child = NULL;
   297
   298                  FR_PROTO_HEX_DUMP(p, (end - p), "fr_struct_from_network - substruct");
   299
   300                  /*
   301                   *      Nothing more to decode, don't decode it.
   302                   */
   303                  if (p >= end) goto done;
   304
   305                  enumv = fr_dict_enum_by_value(key_vp->da, &key_vp->data);
   306                  if (enumv) child = enumv->child_struct[0];
   307
   308                  if (!child) {
   309                  unknown_child:
   310                          /*
   311                           *      Encode the unknown child as attribute
   312                           *      number 0.  This choice means we don't
   313                           *      have to look up, or keep track of, the
   314                           *      number of children of the key field.
   315                           */
   316                          child = fr_dict_unknown_afrom_fields(ctx, key_vp->da,
   317                                                               fr_dict_vendor_num_by_da(key_vp->da), 0);
   318                          if (!child) goto unknown;
   319
   320                          vp = fr_raw_from_network(ctx, child, p, end - p);
   321                          if (!vp) {
   322                                  fr_dict_unknown_free(&child);
   323                                  return -(p - data);
   324                          }
   325
   326                          fr_dcursor_append(&child_cursor, vp);
   327                          p = end;
   328                  } else {
   329                          fr_assert(child->type == FR_TYPE_STRUCT);
   330
   331                          slen = fr_struct_from_network(ctx, &child_cursor, child, p, end - p,
   332                                                        decode_ctx, decode_value, decode_tlv);
   333                          if (slen <= 0) goto unknown_child;
   334                          p += slen;
   335                  }
   336
   337                  fr_dict_unknown_free(&child);
   338
   339                  fr_dcursor_head(&child_cursor);
   340                  fr_dcursor_tail(cursor);
   341                  fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   342
   343                  /*
   344                   *      Else return whatever we decoded.  Note that if
   345                   *      the substruct ends in a TLV, we decode only
   346                   *      the fixed-length portion of the structure.
   347                   */
   348                  return p - data;
   349          }
   350
   351  done:
   352          fr_dcursor_head(&child_cursor);
   353          fr_dcursor_tail(cursor);
   354          fr_dcursor_merge(cursor, &child_cursor);        /* Wind to the end of the new pairs */
   355
   356          return data_len;
   357  }
